/**
 * Tiny 8×6 images carrying metadata, generated with Pillow 12 (see the
 * metadata tests). EXIF: Apple iPhone 15, orientation 6, 2026:10:29 14:03:22,
 * serial SN12345, GPS 27°42'30" N 85°19'26.4" E, 1400 m. Base64 so the tests
 * need no binary files.
 */
const decode = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const JPEG_EXIF = decode(
  "",
);

export const PNG_EXIF = decode(
  "",
);

export const WEBP_EXIF = decode(
  "",
);

export const WEBP_PLAIN = decode(
  "UklGRlIAAABXRUJQVlA4IEYAAADwAgCdASoIAAYAAUAmJagCdLoBQAPwArv/cAARgdyswAD+++FaQ///EtA6c87r8v2cHTdVP/iWdCXQ/+7BdTFflmf9PgAA",
);

export const PNG_PLAIN = decode(
  "iVBORw0KGgoAAAANSUhEUgAAAAgAAAAGCAIAAABxZ0isAAAAGklEQVR4XmMU0bjDAANbvjnB2UxwFhqghwQAqxMDEBm0jm0AAAAASUVORK5CYII=",
);

